/**
 * Página de Gestión de Usuarios
 */

'use client';

import { useState } from 'react';

interface User {
  id: string;
  name: string;
  email: string;
  role: 'admin' | 'user' | 'viewer';
  status: 'active' | 'inactive';
  createdAt: string;
}

export default function UsersPage() {
  const [users, setUsers] = useState<User[]>([
    {
      id: '1',
      name: 'Admin User',
      email: 'admin@example.com',
      role: 'admin',
      status: 'active',
      createdAt: '2024-01-01',
    },
    {
      id: '2',
      name: 'Developer',
      email: 'dev@example.com',
      role: 'user',
      status: 'active',
      createdAt: '2024-01-05',
    },
  ]);

  const roleLabels: Record<string, string> = {
    admin: '👑 Admin',
    user: '👤 Usuario',
    viewer: '👁️ Visor',
  };

  return (
    <div className="space-y-6" style={{ color: 'var(--foreground)' }}>
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold" style={{ color: 'var(--foreground)' }}>Gestión de Usuarios</h1>
        <button className="text-white px-6 py-2 rounded-lg transition" style={{ backgroundColor: 'var(--primary)' }}
          onMouseEnter={(e) => (e.currentTarget.style.opacity = '0.9')}
          onMouseLeave={(e) => (e.currentTarget.style.opacity = '1')}
        >
          + Nuevo Usuario
        </button>
      </div>

      <div className="rounded-lg shadow overflow-hidden" style={{ backgroundColor: 'var(--panel)' }}>
        <table className="w-full">
          <thead className="border-b" style={{ backgroundColor: 'var(--panel-strong)', borderColor: 'var(--stroke)' }}>
            <tr>
              <th className="px-6 py-3 text-left text-sm font-semibold" style={{ color: 'var(--foreground)' }}>Nombre</th>
              <th className="px-6 py-3 text-left text-sm font-semibold" style={{ color: 'var(--foreground)' }}>Email</th>
              <th className="px-6 py-3 text-left text-sm font-semibold" style={{ color: 'var(--foreground)' }}>Rol</th>
              <th className="px-6 py-3 text-left text-sm font-semibold" style={{ color: 'var(--foreground)' }}>Estado</th>
              <th className="px-6 py-3 text-left text-sm font-semibold" style={{ color: 'var(--foreground)' }}>Creado</th>
              <th className="px-6 py-3 text-left text-sm font-semibold" style={{ color: 'var(--foreground)' }}>Acciones</th>
            </tr>
          </thead>
          <tbody>
            {users.map((user) => (
              <tr key={user.id} className="border-b transition" style={{ borderColor: 'var(--stroke)' }}
                onMouseEnter={(e) => (e.currentTarget.style.backgroundColor = 'var(--panel-strong)')}
                onMouseLeave={(e) => (e.currentTarget.style.backgroundColor = 'transparent')}>
                <td className="px-6 py-4 font-medium" style={{ color: 'var(--foreground)' }}>{user.name}</td>
                <td className="px-6 py-4" style={{ color: 'var(--muted)' }}>{user.email}</td>
                <td className="px-6 py-4">
                  <span className="inline-flex items-center px-3 py-1 rounded-full text-sm font-medium" style={{ backgroundColor: 'var(--panel-strong)', color: 'var(--foreground)' }}>
                    {roleLabels[user.role]}
                  </span>
                </td>
                <td className="px-6 py-4">
                  {user.status === 'active' ? (
                    <span className="inline-flex items-center px-3 py-1 rounded-full text-xs font-medium" style={{ backgroundColor: 'rgba(99, 164, 255, 0.2)', color: 'var(--primary)' }}>
                      ✓ Activo
                    </span>
                  ) : (
                    <span className="inline-flex items-center px-3 py-1 rounded-full text-xs font-medium" style={{ backgroundColor: 'var(--panel-strong)', color: 'var(--muted)' }}>
                      ✗ Inactivo
                    </span>
                  )}
                </td>
                <td className="px-6 py-4 text-sm" style={{ color: 'var(--muted)' }}>{user.createdAt}</td>
                <td className="px-6 py-4 space-x-3">
                  <button className="hover:underline text-sm transition" style={{ color: 'var(--primary)' }}>Editar</button>
                  <button className="hover:underline text-sm transition" style={{ color: 'var(--accent)' }}>Suspender</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
